maxVotes: number;
onImageClick: (data: { canteenName: string; canteen: { week: string; openingHours: string }; mainDish?: { dish: string; allergens: { id: string; name: string }[]; isMain: boolean }; sideDishes?: { dish: string; allergens: { id: string; name: string }[]; isMain: boolean }[]; mainAllergens?: { id: string; name: string }[]; description?: string | null; displayDishName?: string | null; origin?: { code: string; country: string } | null; imagePath?: string; highResImagePath?: string; isOutdated?: boolean; isAhead?: boolean; canteenWeekNum?: number; availabilityNotes?: string[] }) => void;
