dtsPropsFor.AllClosedCard:
/**
 * Replaces the WHOLE row when every canteen is shut — one wide card, never
 * three ClosedCards. Reads its place setting from closedCanteens[0].imagePath;
 * see ClosedCard for the three cutlery-and-napkin variants and how one is
 * chosen. Lists each canteen with its usual hours underneath.
 */
closedCanteens: { canteenName: string; canteen: { week: string; openingHours: string }; mainDish?: { dish: string; allergens: { id: string; name: string }[]; isMain: boolean }; sideDishes?: { dish: string; allergens: { id: string; name: string }[]; isMain: boolean }[]; mainAllergens?: { id: string; name: string }[]; description?: string | null; displayDishName?: string | null; origin?: { code: string; country: string } | null; imagePath?: string; highResImagePath?: string; isOutdated?: boolean; isAhead?: boolean; canteenWeekNum?: number; availabilityNotes?: string[] }[];

dtsPropsFor.AppHeader:
mode: 'weekday-current' | 'weekend-preview' | 'weekend-recap' | 'pinned-week';
displayWeek: number;
/** Full name of the selected weekday, e.g. "Mandag". */
dayLabel: string;
/** The selected day's date, e.g. "17. august". */
dateStr: string;
/**
